\"\"\"Send private text prompts to the OpenAI Responses API.

This module uses only the Python standard library. Prompt text is sent in the
HTTPS request body and is not written to disk, logged, or placed in process
arguments. Requests set "'``store`` to false so the API is not asked to retain
the response for later retrieval.
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any


DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_TIMEOUT_SECONDS = 60.0

__all__ = [
    "DEFAULT_BASE_URL",
    "OpenAIClient",
    "OpenAIClientError",
    "send_prompt",
]


class OpenAIClientError(Exception):
    """A request failed before a private text response could be returned."""

    def __init__(self, message: str, *, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


class _RefuseRedirects(urllib.request.HTTPRedirectHandler):
    """Keep prompt bodies from following a redirect to another host."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise OpenAIClientError(
            f"Refusing to follow an HTTP redirect ({code}) from the Responses API"
        )


class OpenAIClient:
    """Minimal client for ``POST /v1/responses`` text prompts."""

    def __init__(
        self,
        api_key: str | None = None,
        *,
        model: str | None = None,
        base_url: str | None = None,
        timeout: float = DEFAULT_TIMEOUT_SECONDS,
    ) -> None:
        resolved_key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY", "")
        resolved_model = model if model is not None else os.environ.get("OPENAI_MODEL", "")
        resolved_base = base_url if base_url is not None else os.environ.get("OPENAI_BASE_URL", "")

        self.api_key = [REDACTED_SECRET]
        self.model = resolved_model.strip()
        self.base_url = (resolved_base.strip() or DEFAULT_BASE_URL).rstrip("/")
        self.timeout = timeout

        if not self.api_key:
            raise OpenAIClientError("Set OPENAI_API_KEY or pass api_key")
        if not self.model:
            raise OpenAIClientError("Set OPENAI_MODEL or pass model")
        if not self.base_url.startswith("https://"):
            raise OpenAIClientError("The Responses API base URL must use HTTPS")
        if self.timeout <= 0:
            raise OpenAIClientError("timeout must be positive")

        self._opener = urllib.request.build_opener(_RefuseRedirects)

    def send_prompt(
        self,
        prompt: str,
        *,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
    ) -> str:
        """Send one private text prompt and return the assistant text."""
        response = self.create_response(
            prompt,
            instructions=instructions,
            max_output_tokens=max_output_tokens,
            temperature=temperature,
        )
        return output_text(response)

    def create_response(
        self,
        prompt: str,
        *,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
    ) -> dict[str, Any]:
        """Send one private text prompt and return the parsed response object."""
        body = _request_body(
            prompt,
            model=self.model,
            instructions=instructions,
            max_output_tokens=max_output_tokens,
            temperature=temperature,
        )
        request = urllib.request.Request(
            f"{self.base_url}/responses",
            data=json.dumps(body, ensure_ascii=False).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
            method="POST",
        )
        try:
            with self._opener.open(request, timeout=self.timeout) as http_response:
                raw = http_response.read()
                status = getattr(http_response, "status", None)
        except urllib.error.HTTPError as exc:
            raise OpenAIClientError(_http_error_message(exc), status=exc.code) from None
        except OpenAIClientError:
            raise
        except urllib.error.URLError:
            raise OpenAIClientError("Could not reach the Responses API") from None
        except TimeoutError:
            raise OpenAIClientError("The Responses API request timed out") from None

        try:
            payload = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise OpenAIClientError(
                "The Responses API returned a non-JSON body",
                status=status,
            ) from None
        if not isinstance(payload, dict):
            raise OpenAIClientError(
                "The Responses API returned an unexpected response",
                status=status,
            )
        return payload


def send_prompt(
    prompt: str,
    *,
    api_key: str | None = None,
    model: str | None = None,
    base_url: str | None = None,
    timeout: float = DEFAULT_TIMEOUT_SECONDS,
    instructions: str | None = None,
    max_output_tokens: int | None = None,
    temperature: float | None = None,
) -> str:
    """Send one private text prompt with a short-lived client."""
    client = OpenAIClient(
        api_key,
        model=model,
        base_url=base_url,
        timeout=timeout,
    )
    return client.send_prompt(
        prompt,
        instructions=instructions,
        max_output_tokens=max_output_tokens,
        temperature=temperature,
    )


def output_text(response: dict[str, Any]) -> str:
    """Collect assistant text from a Responses API object."""
    if not isinstance(response, dict):
        raise OpenAIClientError("Response object must be a dictionary")

    error = response.get("error")
    if error:
        raise OpenAIClientError(_api_error_message(error))

    status = response.get("status")
    if status not in (None, "completed"):
        raise OpenAIClientError(f"Response status is {status}")

    chunks: list[str] = []
    output = response.get("output")
    if isinstance(output, list):
        for item in output:
            chunks.extend(_text_from_item(item))

    if not chunks and isinstance(response.get("output_text"), str):
        chunks.append(response["output_text"])
    if not chunks:
        raise OpenAIClientError("Response did not include text output")
    return "".join(chunks)


def _request_body(
    prompt: str,
    *,
    model: str,
    instructions: str | None,
    max_output_tokens: int | None,
    temperature: float | None,
) -> dict[str, Any]:
    if not isinstance(prompt, str) or prompt.strip() == "":
        raise OpenAIClientError("Prompt must be a non-empty string")
    if instructions is not None and not isinstance(instructions, str):
        raise OpenAIClientError("instructions must be a string")
    if max_output_tokens is not None and (
        type(max_output_tokens) is not int or max_output_tokens < 1
    ):
        raise OpenAIClientError("max_output_tokens must be a positive integer")
    if temperature is not None and not isinstance(temperature, (int, float)):
        raise OpenAIClientError("temperature must be a number")

    body: dict[str, Any] = {
        "model": model,
        "input": prompt,
        "store": False,
    }
    if instructions is not None:
        body["instructions"] = instructions
    if max_output_tokens is not None:
        body["max_output_tokens"] = max_output_tokens
    if temperature is not None:
        body["temperature"] = temperature
    return body


def _text_from_item(item: Any) -> list[str]:
    if not isinstance(item, dict):
        return []
    item_type = item.get("type")
    if item_type == "output_text" and isinstance(item.get("text"), str):
        return [item["text"]]
    if item_type != "message":
        return []

    chunks: list[str] = []
    content = item.get("content")
    if not isinstance(content, list):
        return chunks
    for part in content:
        if not isinstance(part, dict):
            continue
        if part.get("type") in {"output_text", "text"} and isinstance(part.get("text"), str):
            chunks.append(part["text"])
        elif part.get("type") == "refusal" and isinstance(part.get("refusal"), str):
            raise OpenAIClientError("The model refused the prompt")
    return chunks


def _http_error_message(exc: urllib.error.HTTPError) -> str:
    try:
        raw = exc.read()
    except Exception:
        raw = b""
    if raw:
        try:
            payload = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            payload = None
        if isinstance(payload, dict) and payload.get("error") is not None:
            return _api_error_message(payload["error"])
    return f"Responses API request failed with HTTP {exc.code}"


def _api_error_message(error: Any) -> str:
    if isinstance(error, dict):
        message = error.get("message")
        if isinstance(message, str) and message.strip():
            return message.strip()[:500]
    if isinstance(error, str) and error.strip():
        return error.strip()[:500]
    return "Responses API returned an error"


def main(argv: list[str] | None = None) -> int:
    """Read a prompt from stdin so it is not exposed in the process list."""
    args = list(sys.argv[1:] if argv is None else argv)
    model: str | None = None
    if args and args[0] == "--model":
        if len(args) != 2:
            print("Usage: python openai_client.py [--model MODEL] < prompt.txt", file=sys.stderr)
            return 2
        model = args[1]
    elif args:
        print("Usage: python openai_client.py [--model MODEL] < prompt.txt", file=sys.stderr)
        return 2

    prompt = sys.stdin.read()
    try:
        text = send_prompt(prompt, model=model)
    except OpenAIClientError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    sys.stdout.write(text)
    if not text.endswith("'"\\n\"):
        sys.stdout.write(\"\\n\")
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
